package com.getcapacitor;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

/** Executes actual delivery/retention policy under queued UI and blocked worker interleavings. */
public final class BridgeReplyScopeTest {
    static int tests,assertions;static void check(boolean value){assertions++;if(!value)throw new AssertionError("Bridge reply scope assertion failed");}
    static final class Ui implements Executor {final Queue<Runnable> queue=new ConcurrentLinkedQueue<>();final Thread owner=Thread.currentThread();public void execute(Runnable work){queue.add(work);}void drain(){check(Thread.currentThread()==owner);Runnable next;while((next=queue.poll())!=null)next.run();}}
    public static void main(String[] args)throws Exception{
        tests++;BridgeReplyScope scope=new BridgeReplyScope();Ui ui=new Ui();AtomicInteger invoked=new AtomicInteger();BridgeReplyScope.Ticket first=scope.capture();Thread producer=new Thread(()->scope.post(first,ui,()->{check(Thread.currentThread()==ui.owner);invoked.incrementAndGet();}));producer.start();producer.join(2000);check(!producer.isAlive()&&invoked.get()==0);ui.drain();check(invoked.get()==1);
        tests++;scope.post(first,ui,invoked::incrementAndGet);scope.close();ui.drain();check(invoked.get()==1&&!scope.accepts(first));check(!scope.post(scope.capture(),ui,invoked::incrementAndGet));check(!scope.advance());ui.drain();check(invoked.get()==1);
        tests++;BridgeReplyScope document=new BridgeReplyScope();BridgeReplyScope.Ticket old=document.capture();document.post(old,ui,invoked::incrementAndGet);check(document.advance());BridgeReplyScope.Ticket current=document.capture();check(document.advance());check(!document.accepts(old)&&!document.accepts(current));BridgeReplyScope.Ticket newest=document.capture();document.post(newest,ui,invoked::incrementAndGet);ui.drain();check(invoked.get()==2);BridgeReplyScope other=new BridgeReplyScope();check(!other.accepts(newest)&&!document.accepts(other.capture()));
        tests++;BridgeReplyScope saves=new BridgeReplyScope();ConcurrentMap<String,Object> retained=new ConcurrentHashMap<>();Object staleCall=new Object(),newCall=new Object();BridgeReplyScope.Ticket stale=saves.capture();CountDownLatch checked=new CountDownLatch(1),release=new CountDownLatch(1);AtomicBoolean retainedOld=new AtomicBoolean(true);Thread late=new Thread(()->{check(saves.accepts(stale));checked.countDown();try{if(!release.await(2,TimeUnit.SECONDS))throw new AssertionError();}catch(InterruptedException interrupted){throw new AssertionError(interrupted);}retainedOld.set(saves.retain(stale,retained,"callback-1",staleCall));});late.start();check(checked.await(2,TimeUnit.SECONDS));saves.advanceAndClear(retained);BridgeReplyScope.Ticket next=saves.capture();check(saves.retain(next,retained,"callback-1",newCall));release.countDown();late.join(2000);check(!late.isAlive()&&!retainedOld.get()&&retained.get("callback-1")==newCall);check(!retained.remove("callback-1",staleCall)&&retained.get("callback-1")==newCall);
        tests++;BridgeReplyScope inside=new BridgeReplyScope();CountDownLatch putEntered=new CountDownLatch(1),putRelease=new CountDownLatch(1),navRequested=new CountDownLatch(1),navFinished=new CountDownLatch(1);Map<String,Object> blocking=new ConcurrentHashMap<String,Object>(){@Override public Object put(String key,Object value){putEntered.countDown();try{if(!putRelease.await(2,TimeUnit.SECONDS))throw new AssertionError();}catch(InterruptedException interrupted){throw new AssertionError(interrupted);}return super.put(key,value);}};BridgeReplyScope.Ticket before=inside.capture();Thread saver=new Thread(()->inside.retain(before,blocking,"callback-1",staleCall));saver.start();check(putEntered.await(2,TimeUnit.SECONDS));Thread navigation=new Thread(()->{navRequested.countDown();inside.advanceAndClear(blocking);navFinished.countDown();});navigation.start();check(navRequested.await(2,TimeUnit.SECONDS));check(!navFinished.await(50,TimeUnit.MILLISECONDS));putRelease.countDown();saver.join(2000);navigation.join(2000);check(!saver.isAlive()&&!navigation.isAlive()&&blocking.isEmpty());check(inside.retain(inside.capture(),blocking,"callback-1",newCall));check(blocking.get("callback-1")==newCall);
        tests++;BridgeReplyScope oldView=new BridgeReplyScope(),newView=new BridgeReplyScope();BridgeReplyScope.Ticket oldViewCall=oldView.capture(),newViewCall=newView.capture();oldView.close();check(!oldView.accepts(oldViewCall)&&newView.accepts(newViewCall));newView.post(newViewCall,ui,invoked::incrementAndGet);ui.drain();check(invoked.get()==3);
        System.out.println("{\"status\":\"passed\",\"testCount\":"+tests+",\"assertionCount\":"+assertions+"}");
    }
}
